package com.guocheng.mediapocket;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.lang.reflect.*;
public final class OnlineSubtitleSearch {
 static final ExecutorService IO=Executors.newFixedThreadPool(4);
 static Object field(Object target,String name){for(Class<?> c=target.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);return f.get(target);}catch(Exception ignored){}return null;}
 static Object call(Object target,String name,Class<?>[] types,Object...args)throws Exception{for(Class<?> c=target.getClass();c!=null;c=c.getSuperclass())try{Method m=c.getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(target,args);}catch(NoSuchMethodException ignored){}throw new NoSuchMethodException(name);}
 public static void start(Object session){Object owner=field(session,"a");if(!(owner instanceof Activity))return;Activity a=(Activity)owner;JSONArray subs=SourceSubtitleLoader.list(a);new AlertDialog.Builder(a).setTitle("字幕来源").setItems(new String[]{"线路外挂字幕 · "+(subs==null?0:subs.length())+" 条","内嵌字幕轨","在线字幕插件搜索","字幕查询诊断"},(d,n)->{if(n==0)SourceSubtitleLoader.choose(a);else if(n==1)embedded(a);else if(n==2)online(session);else diagnostic(a);}).setNegativeButton("取消",null).show();}
 public static void online(Object session){Object owner=field(session,"a");if(!(owner instanceof Activity))return;Activity a=(Activity)owner;if(a.isFinishing())return;JSONObject meta=field(a,"meta") instanceof JSONObject?(JSONObject)field(a,"meta"):new JSONObject();SharedPreferences prefs=a.getSharedPreferences("data",0);String id=String.valueOf(field(a,"id"));JSONObject identity;try{identity=new JSONObject(meta.toString());identity.put("name",meta.optString("fusion.title",meta.optString("name")));}catch(Exception e){identity=meta;}final JSONObject matchMeta=identity;JSONObject match=FusionArtwork.cached(a,identity);String suggested=meta.optString("fusion.imdb",match==null?MediaMatchRules.imdb(id):match.optString("id"));String type=meta.optString("fusion.mediaType",match==null?String.valueOf(field(a,"type")):match.optString("type"));FusionPlaybackRules.Episode parsed=FusionPlaybackRules.episode(meta.optString("subtitleEpisode",meta.optString("name")),meta.optString("fusion.title"));int[] ep=new int[]{parsed.season>=0?parsed.season:1,parsed.number>0?parsed.number:1};if(match==null&&meta.optString("fusion.mediaType").isEmpty()&&parsed.number>0)type="series";String[] parts=id.split(":");if(parts.length==3)try{ep=new int[]{Integer.parseInt(parts[1]),Integer.parseInt(parts[2])};}catch(Exception ignored){}
  LinearLayout form=new LinearLayout(a);form.setOrientation(1);int pad=(int)(16*a.getResources().getDisplayMetrics().density);form.setPadding(pad,0,pad,0);EditText input=new EditText(a);input.setSingleLine(true);input.setHint("影片名称或 IMDb ID（tt…）");input.setText(suggested.isEmpty()?MediaMatchRules.clean(meta.optString("fusion.title",meta.optString("name"))):suggested);form.addView(input);Spinner kind=new Spinner(a);kind.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"电影","剧集"}));kind.setSelection("series".equals(type)?1:0);form.addView(kind);LinearLayout episodes=new LinearLayout(a);EditText season=new EditText(a),episode=new EditText(a);season.setInputType(2);episode.setInputType(2);season.setHint("季");episode.setHint("集");season.setText(String.valueOf(ep[0]));episode.setText(String.valueOf(ep[1]));episodes.addView(season,new LinearLayout.LayoutParams(0,-2,1));episodes.addView(episode,new LinearLayout.LayoutParams(0,-2,1));form.addView(episodes);Spinner language=new Spinner(a);language.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"中文优先","英语优先","全部语言"}));String languagePref=prefs.getString("subtitleLanguage","zho");language.setSelection(languagePref.equals("eng")?1:languagePref.equals("all")?2:0);form.addView(language);TextView note=new TextView(a);note.setText("使用已安装的字幕插件；影视仓需先确认对应影片和季集。结果保留其他语言并优先排序。");form.addView(note);
  AlertDialog dialog=new AlertDialog.Builder(a).setTitle("在线字幕搜索").setView(form).setPositiveButton("搜索",null).setNeutralButton("内嵌字幕",(d,n)->embedded(a)).setNegativeButton("取消",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{int s,e;try{s=Integer.parseInt(season.getText().toString());e=Integer.parseInt(episode.getText().toString());if(s<0||e<1)throw new Exception();}catch(Exception bad){note.setText("请填写有效的季、集数字");return;}if(input.getText().toString().trim().isEmpty()){note.setText("请填写片名或 IMDb ID");return;}String mediaType=kind.getSelectedItemPosition()==1?"series":"movie",lang=new String[]{"zho","eng","all"}[language.getSelectedItemPosition()];prefs.edit().putString("subtitleLanguage",lang).apply();String word=input.getText().toString().trim(),imdb=MediaMatchRules.imdb(word);dialog.dismiss();if(!imdb.isEmpty())query(a,imdb,mediaType,s,e,lang);else match(a,word,mediaType,s,e,lang,matchMeta);}));dialog.show();
 }
 static void match(Activity a,String word,String type,int season,int episode,String lang,JSONObject meta){ProgressDialog wait=ProgressDialog.show(a,"匹配影片","正在搜索…",true,true);IO.execute(()->{try{JSONArray candidates=FusionArtwork.search(word);ArrayList<JSONObject> items=new ArrayList<>();for(int i=0;i<candidates.length();i++){JSONObject c=candidates.optJSONObject(i);if(c!=null&&type.equals(c.optString("type")))items.add(c);}a.runOnUiThread(()->{if(a.isFinishing())return;wait.dismiss();if(items.isEmpty()){message(a,"没有匹配到影片，请使用 IMDb ID 或英文名重试。");return;}String[] labels=new String[items.size()];for(int i=0;i<labels.length;i++)labels[i]=items.get(i).optString("name")+" · "+items.get(i).optString("releaseInfo");new AlertDialog.Builder(a).setTitle("确认字幕对应影片").setItems(labels,(d,n)->{JSONObject chosen=items.get(n);FusionArtwork.save(a,meta,chosen);query(a,chosen.optString("id"),type,season,episode,lang);}).show();});}catch(Exception e){a.runOnUiThread(()->{if(!a.isFinishing()){wait.dismiss();message(a,"影片匹配失败："+e.getClass().getSimpleName());}});}});}
 static void query(Activity a,String imdb,String type,int season,int episode,String lang){SharedPreferences prefs=a.getSharedPreferences("data",0);String id=imdb+(type.equals("series")?":"+season+":"+episode:"");JSONArray addons;try{addons=new JSONArray(prefs.getString("addons","[]"));}catch(Exception e){addons=new JSONArray();}JSONArray providers=AddonRegistry.forResource(addons,"subtitles",type,id);if(providers.length()==0){prefs.edit().putString("subtitleReport","查询编号："+id+"\n类型："+type+"\n已安装插件："+addons.length()+"\n兼容字幕插件：0\n插件声明的影片类型或编号前缀不匹配。 ").apply();message(a,"没有兼容此影片身份的字幕插件。请到插件市场添加字幕插件，或在插件页恢复三个默认插件。");return;}ProgressDialog wait=ProgressDialog.show(a,"搜索字幕",id+" · 正在查询 "+providers.length()+" 个插件",true,true);final boolean[] cancelled={false};wait.setOnCancelListener(d->cancelled[0]=true);final JSONArray list=providers;IO.execute(()->{ExecutorService tasks=Executors.newFixedThreadPool(3);CompletionService<JSONObject> jobs=new ExecutorCompletionService<>(tasks);ArrayList<Future<JSONObject>> futures=new ArrayList<>();for(int i=0;i<Math.min(8,list.length());i++){JSONObject provider=list.optJSONObject(i);if(provider==null)continue;futures.add(jobs.submit(()->{JSONObject result=new JSONObject().put("provider",provider.optString("name","字幕插件"));try{JSONObject response=CinemaCatalogClient.json(provider.optString("base")+"/subtitles/"+type+"/"+Net.esc(id)+".json");JSONArray subs=response.optJSONArray("subtitles");result.put("items",subs);if(subs==null||subs.length()==0){String warning=response.optString("error",response.optString("message"));if(!warning.isEmpty())result.put("error",warning.replaceAll("(?i)https?://[^\\s]+","[地址]"));}}catch(Exception e){result.put("error",e.getMessage()==null?e.getClass().getSimpleName():e.getMessage().replaceAll("(?i)https?://[^\\s]+","[地址已隐藏]"));}return result;}));}LinkedHashMap<String,JSONObject> found=new LinkedHashMap<>();StringBuilder report=new StringBuilder("查询编号："+id+"\n类型："+type+" · 语言优先："+lang+"\n兼容字幕插件："+list.length()+" · 本次最多查询8个\n");int completed=0;long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(20);try{for(int i=0;i<futures.size()&&!cancelled[0];i++){long remaining=deadline-System.nanoTime();if(remaining<=0)break;Future<JSONObject> f=jobs.poll(remaining,TimeUnit.NANOSECONDS);if(f==null)break;JSONObject r=f.get();completed++;JSONArray items=r.optJSONArray("items");report.append(r.optString("provider")).append("：").append(r.has("error")?r.optString("error"):"返回 "+(items==null?0:items.length())+" 条").append('\n');for(int j=0;items!=null&&j<Math.min(300,items.length());j++){JSONObject item=items.optJSONObject(j);if(item==null)continue;String url=item.optString("url");if(url.startsWith("https://")||url.startsWith("http://")){item.put("provider",r.optString("provider"));found.putIfAbsent(url,item);}}}}catch(Exception ignored){}finally{for(Future<?> f:futures)f.cancel(true);tasks.shutdownNow();}report.append("已完成查询：").append(completed).append(" / ").append(futures.size()).append("\n可加载地址：").append(found.size()).append("\n");if(completed<futures.size())report.append("部分查询未在20秒内完成。\n");prefs.edit().putString("subtitleReport",report.toString()).apply();ArrayList<JSONObject> results=new ArrayList<>(found.values());results.sort((x,y)->Integer.compare(rank(x.optString("lang"),lang),rank(y.optString("lang"),lang)));a.runOnUiThread(()->{if(a.isFinishing()||cancelled[0])return;wait.dismiss();if(results.isEmpty()){message(a,"没有找到可加载字幕。\n"+report+"请核对影片、季集，也可使用字幕菜单的粘贴地址。");return;}String[] labels=new String[results.size()];for(int i=0;i<labels.length;i++){JSONObject v=results.get(i);labels[i]=v.optString("lang","未知语言")+" · "+v.optString("provider")+" · "+v.optString("id","字幕");}new AlertDialog.Builder(a).setTitle("选择字幕 · "+labels.length+" 条").setItems(labels,(d,n)->{try{SourceSubtitleLoader.load(a,new JSONArray().put(results.get(n)),false);}catch(Exception e){message(a,"字幕加载入口调用失败");}}).setPositiveButton("自动尝试字幕",(d,n)->{JSONArray options=new JSONArray();for(JSONObject result:results)options.put(result);SourceSubtitleLoader.load(a,options,true);}).setNegativeButton("取消",null).show();});});}
 static synchronized void subtitleEvent(Activity a,String event){SharedPreferences p=a.getSharedPreferences("data",0);String old=p.getString("subtitleReport","");String next=old+"\n"+event;p.edit().putString("subtitleReport",next.length()>8000?next.substring(next.length()-8000):next).apply();}
 static void diagnostic(Activity a){String report=a.getSharedPreferences("data",0).getString("subtitleReport","尚未进行在线字幕查询，请先选择在线字幕插件搜索。");new AlertDialog.Builder(a).setTitle("字幕查询诊断").setMessage(report).setPositiveButton("复制",(d,n)->{android.content.ClipboardManager clipboard=(android.content.ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE);clipboard.setPrimaryClip(ClipData.newPlainText("字幕诊断",report));}).setNegativeButton("关闭",null).show();}
 static int rank(String language,String preferred){String l=language.toLowerCase(Locale.ROOT);boolean zh=l.equals("zh")||l.equals("zho")||l.equals("chi")||l.startsWith("zh-")||l.contains("中文")||l.contains("简体")||l.contains("繁体");boolean en=l.equals("en")||l.equals("eng")||l.startsWith("en-");return preferred.equals("all")?0:preferred.equals("eng")?(en?0:zh?1:2):(zh?0:en?1:2);}
 static void embedded(Activity a){Object video=field(a,"video"),player=video==null?null:field(video,"player");if(player==null){message(a,"播放器尚未就绪");return;}try{Object tracks=call(player,"getSpuTracks",new Class<?>[0]);ArrayList<Object> available=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();if(tracks instanceof Object[])for(Object track:(Object[])tracks){Object id=field(track,"id");if(id instanceof Integer&&(Integer)id>=0){available.add(track);labels.add(String.valueOf(field(track,"name")));}}if(available.isEmpty()){message(a,"当前视频没有已识别的内嵌字幕轨");return;}new AlertDialog.Builder(a).setTitle("内嵌字幕轨").setItems(labels.toArray(new String[0]),(d,n)->{try{call(player,"setSpuTrack",new Class<?>[]{int.class},field(available.get(n),"id"));}catch(Exception e){message(a,"选择字幕轨失败");}}).show();}catch(Exception e){message(a,"此播放器暂不支持内嵌字幕选择；可使用在线字幕或字幕地址。");}}
 static void message(Activity a,String text){if(!a.isFinishing())new AlertDialog.Builder(a).setTitle("字幕").setMessage(text).setPositiveButton("确定",null).show();}
}
